exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  02 · build query                                            ★★☆ core
//  concepts: query composition · percent-encoding
// ─────────────────────────────────────────────────────────────────────────
//
//  Turn an ordered list of key/value pairs into "?a=1&b=2" — escaped,
//  and with no dangling "?" when there is nothing to send.

using static Bootcamp.Check;

string BuildQuery(List<(string Key, string Value)> pairs)
{
    if (pairs.Count == 0) return "";
    return "?" + string.Join("&", pairs.Select(p => $"{Uri.EscapeDataString(p.Key)}={Uri.EscapeDataString(p.Value)}"));
}

exercises.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("[(page, 2), (q, a b)] -> \"?page=2&q=a%20b\"", () =>
    Eq(BuildQuery([("page", "2"), ("q", "a b")]), "?page=2&q=a%20b"));

Test("[] -> \"\" (boundary: no dangling question mark)", () =>
    Eq(BuildQuery([]), ""));

Test("a single pair -> \"?sort=name\"", () =>
    Eq(BuildQuery([("sort", "name")]), "?sort=name"));

Test("a value full of reserved characters is escaped whole", () =>
    Eq(BuildQuery([("redirect", "/home?x=1")]), "?redirect=%2Fhome%3Fx%3D1"));

