exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  03 · parse query                                            ★★★ stretch
//  concepts: tolerant parsing · plus vs %2B
// ─────────────────────────────────────────────────────────────────────────
//
//  The inbound half: "?a=1&b=two%20words" into a dictionary. Bare keys,
//  duplicates and the two faces of "+" must all behave predictably.

using static Bootcamp.Check;

Dictionary<string, string> ParseQuery(string query)
{
    var result = new Dictionary<string, string>();
    if (query.StartsWith('?')) query = query[1..];
    if (query.Length == 0) return result;
    foreach (var piece in query.Split('&'))
    {
        if (piece.Length == 0) continue;
        var eq = piece.IndexOf('=');
        var key = eq < 0 ? piece : piece[..eq];
        var value = eq < 0 ? "" : piece[(eq + 1)..];
        result[Decode(key)] = Decode(value);
    }
    return result;

    static string Decode(string s) => Uri.UnescapeDataString(s.Replace('+', ' '));
}

exercises.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("\"?a=1&b=two%20words\" -> {a: 1, b: two words}", () =>
    Eq(ParseQuery("?a=1&b=two%20words"), new Dictionary<string, string> { ["a"] = "1", ["b"] = "two words" }));

Test("\"a=1&a=2\" -> {a: 2} (the later duplicate wins)", () =>
    Eq(ParseQuery("a=1&a=2"), new Dictionary<string, string> { ["a"] = "2" }));

Test("\"flag\" -> {flag: \"\"} (boundary: a bare key)", () =>
    Eq(ParseQuery("flag"), new Dictionary<string, string> { ["flag"] = "" }));

Test("\"\" -> {} (boundary)", () =>
    Eq(ParseQuery(""), new Dictionary<string, string>()));

Test("\"q=1%2B1&s=a+b\" -> {q: 1+1, s: a b} (the two faces of plus)", () =>
    Eq(ParseQuery("q=1%2B1&s=a+b"), new Dictionary<string, string> { ["q"] = "1+1", ["s"] = "a b" }));

