exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  04 · mask pii                                               ★☆☆ warm-up
//  concepts: masking · index slicing
// ─────────────────────────────────────────────────────────────────────────
//
//  Request logs must never contain a full email or card number. Keep
//  just enough to correlate a support ticket, star out the rest.

using static Bootcamp.Check;

string MaskEmail(string email)
{
    var at = email.IndexOf('@');
    return email[0] + "***" + email[at..];
}

string MaskDigits(string s)
{
    if (s.Length <= 4) return s;
    return new string('*', s.Length - 4) + s[^4..];
}

