exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  05 · route template                                         ★★☆ core
//  concepts: token filling · fail loudly
// ─────────────────────────────────────────────────────────────────────────
//
//  Build "/users/{id}/orders/{orderId}" links from a value bag. A missing
//  value must be a loud error, never a silent "/users//orders/".

using System.Text;
using static Bootcamp.Check;

string Fill(string template, Dictionary<string, string> values)
{
    var sb = new StringBuilder();
    int i = 0;
    while (i < template.Length)
    {
        int open = template.IndexOf('{', i);
        int close = open < 0 ? -1 : template.IndexOf('}', open + 1);
        if (close < 0)
        {
            sb.Append(template, i, template.Length - i);
            break;
        }
        sb.Append(template, i, open - i);
        var name = template[(open + 1)..close];
        if (!values.TryGetValue(name, out var value))
            throw new ArgumentException($"missing route value '{name}'");
        sb.Append(value);
        i = close + 1;
    }
    return sb.ToString();
}

