// ──────────────────────────── tests ──────────────────────────────────────

Test("two tokens are filled", () =>
    Eq(Fill("/users/{id}/orders/{orderId}", new Dictionary<string, string> { ["id"] = "42", ["orderId"] = "a7" }),
       "/users/42/orders/a7"));

Test("a template without tokens is returned unchanged (boundary)", () =>
    Eq(Fill("/health", new Dictionary<string, string> { ["id"] = "42" }), "/health"));

Test("a token with no value throws \"missing route value\"", () =>
    Throws<ArgumentException>(() => Fill("/users/{id}", new Dictionary<string, string>()), "missing route value 'id'"));

Test("the same token twice is filled twice", () =>
    Eq(Fill("/x/{id}/{id}", new Dictionary<string, string> { ["id"] = "3" }), "/x/3/3"));

