exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  06 · link header                                            ★★☆ core
//  concepts: pagination envelope · RFC 8288 Link
// ─────────────────────────────────────────────────────────────────────────
//
//  GitHub-style paging: the response carries a Link header with prev and
//  next URLs. The first page has no prev, the last page no next.

using static Bootcamp.Check;

string LinkHeader(string baseUrl, int page, int totalPages)
{
    var parts = new List<string>();
    if (page > 1) parts.Add($"<{baseUrl}?page={page - 1}>; rel=\"prev\"");
    if (page < totalPages) parts.Add($"<{baseUrl}?page={page + 1}>; rel=\"next\"");
    return string.Join(", ", parts);
}

