    Eq(LinkHeader("/items", 1, 5), "</items?page=2>; rel=\"next\""));

Test("page 5 of 5 -> only prev (boundary: last page)", () =>
    Eq(LinkHeader("/items", 5, 5), "</items?page=4>; rel=\"prev\""));

Test("page 1 of 1 -> \"\" (boundary: a single page)", () =>
    Eq(LinkHeader("/items", 1, 1), ""));

