exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  07 · auth headers                                           ★★★ stretch
//  concepts: header parsing · never throw at the edge
// ─────────────────────────────────────────────────────────────────────────
//
//  The Authorization header is attacker-controlled text. Parse Bearer
//  and Basic forms — and answer null, never an exception, for junk.

using System.Text;
using static Bootcamp.Check;

string? BearerToken(string header)
{
    var h = header.Trim();
    const string scheme = "Bearer ";
    if (!h.StartsWith(scheme, StringComparison.OrdinalIgnoreCase)) return null;
    var token = h[scheme.Length..];
    if (token.Length == 0 || token.Any(char.IsWhiteSpace)) return null;
    return token;
}

(string User, string Pass)? BasicCredentials(string header)
{
    var h = header.Trim();
    const string scheme = "Basic ";
    if (!h.StartsWith(scheme, StringComparison.OrdinalIgnoreCase)) return null;
    string decoded;
    try
    {
        decoded = Encoding.UTF8.GetString(Convert.FromBase64String(h[scheme.Length..]));
    }
    catch (FormatException)
    {
        return null;
    }
    var colon = decoded.IndexOf(':');
    if (colon < 0) return null;
    return (decoded[..colon], decoded[(colon + 1)..]);
}

exercises.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("BearerToken(\"Bearer abc123\") -> \"abc123\"", () =>
    Eq(BearerToken("Bearer abc123"), "abc123"));

Test("BearerToken(\"bearer abc\") -> \"abc\" (the scheme is case-insensitive)", () =>
    Eq(BearerToken("bearer abc"), "abc"));

Test("BearerToken(\"Basic abc\") -> null", () =>
    Eq(BearerToken("Basic abc"), null));

Test("BearerToken(\"\") -> null (boundary)", () =>
    Eq(BearerToken(""), null));

Test("BasicCredentials(\"Basic dXNlcjpwYXNz\") -> (user, pass)", () =>
    Eq(BasicCredentials("Basic dXNlcjpwYXNz"), ("user", "pass")));

Test("a password may contain colons: split at the FIRST one (boundary)", () =>
    Eq(BasicCredentials("Basic dXNlcjpwYTpzcw=="), ("user", "pa:ss")));

Test("BasicCredentials(\"Basic !!!\") -> null (malformed base64 never throws)", () =>
    Eq(BasicCredentials("Basic !!!"), null));

