exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  08 · clean input                                            ★☆☆ warm-up
//  concepts: normalization · whitespace runs
// ─────────────────────────────────────────────────────────────────────────
//
//  "  Jane \t  Doe " and "Jane Doe" must be the same display name, and a
//  name made only of spaces is no name at all.

using static Bootcamp.Check;

string? Clean(string? s)
{
    if (string.IsNullOrWhiteSpace(s)) return null;
    return string.Join(' ', s.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries));
}

